def qr_dir():
    return DATA_DIR / "QR사진"


def qr_path(row):
    return qr_dir() / row["qr"] if row and row["qr"] else None


def remove_qr(con, cid):
    row = con.execute("SELECT qr FROM cards WHERE id=?", (cid,)).fetchone()
    p = qr_path(row)
    if p:
        try:
            p.unlink()
        except OSError:
            pass
    con.execute("UPDATE cards SET qr=NULL WHERE id=?", (cid,))

