# 목록 조회용: 카드 + 카드 정보
EFF_GRADE = "COALESCE(NULLIF(i.grade,''), c.grade)"
FROMX = " FROM cards c LEFT JOIN card_info i ON i.no_key = c.info_key"
SELECT_X = ("SELECT c.*, i.no AS info_no, COALESCE(i.name_ko,'') AS name_ko, COALESCE(i.name_jp,'') AS name_jp, "
            "COALESCE(i.tan,'') AS tan, COALESCE(i.type,'') AS ctype, COALESCE(i.brand,'') AS brand, "
            "COALESCE(i.source,'') AS source, COALESCE(i.part,'') AS part, COALESCE(i.codi,'') AS codi, "
            "COALESCE(i.qty,'') AS qty, COALESCE(i.memo,'') AS info_memo, COALESCE(i.grade,'') AS info_grade, "
            + EFF_GRADE + " AS eff_grade" + FROMX)


RE_YEAR = re.compile(r"(20\d\d)")
RE_TAN_NO = re.compile(r"(\d+)\s*탄")
PART_ORDER = {"상의": 1, "탑스": 1, "하의": 2, "보텀스": 2, "원피스": 3, "슈즈": 4, "신발": 4,
              "악세": 5, "악세서리": 5, "액세서리": 5, "액세": 5}


def tan_rank(t):
    """탄 순서: 1탄~6탄 → 2014 1탄~ → 2015 … → 프로모션(연도순, 연도 없는 프로모션이 맨 끝) → 빈 값"""
    t = nfc(t or "").strip()
    if not t:
        return 99999999
    promo = "프로모션" in t
    y = RE_YEAR.search(t)
    n = RE_TAN_NO.search(t)
    year = int(y.group(1)) if y else (9999 if promo else 0)
    return (1 if promo else 0) * 10000000 + year * 100 + (int(n.group(1)) if n else 0)


RE_DIGITS = re.compile(r"\d+")


def num_key(s):
    """번호 비교용: 숫자를 6자리로 맞춤 ("14 01-02" → "000014000001-000002")"""
    s = re.sub(r"\s+", "", nfc(s or "")).upper()
    return RE_DIGITS.sub(lambda m: m.group(0).zfill(6), s) if s else "~"


def part_rank(p):
    """같은 탄·코디 안에서: 상의 → 하의 → 원피스 → 슈즈 → 악세 → 그 밖"""
    return PART_ORDER.get(nfc(p or "").strip(), 9)


def db():
    con = sqlite3.connect(str(DB_PATH), timeout=30)
    con.row_factory = sqlite3.Row
    con.execute("PRAGMA journal_mode=WAL")
    con.execute("PRAGMA foreign_keys=ON")
    con.create_function("tan_rank", 1, tan_rank)
    con.create_function("part_rank", 1, part_rank)
    con.create_function("num_key", 1, num_key)
    return con


def init_db():
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    STORE.mkdir(parents=True, exist_ok=True)
    con = db()
    con.executescript(SCHEMA)
    con.execute("INSERT OR IGNORE INTO settings(key, value) VALUES('grades', ?)", (DEFAULT_GRADES,))
    # 이전 버전 DB 자동 업그레이드
    cols = [r[1] for r in con.execute("PRAGMA table_info(cards)")]
    if "info_key" not in cols:
        con.execute("ALTER TABLE cards ADD COLUMN info_key TEXT")          # 연결된 카드 정보 번호
    if "info_manual" not in cols:
        con.execute("ALTER TABLE cards ADD COLUMN info_manual INTEGER DEFAULT 0")  # 1: 사용자가 직접 연결
    # 패턴 분류(이미지 분석) 결과
    for col, typ in (("color_main", "TEXT"), ("colors", "TEXT"), ("palette", "TEXT"), ("hash_all", "TEXT"),
                     ("hash_item", "TEXT"), ("orient", "TEXT"), ("sim_group", "INTEGER"), ("feat_ver", "INTEGER")):
        if col not in cols:
            con.execute("ALTER TABLE cards ADD COLUMN %s %s" % (col, typ))
    con.execute("CREATE INDEX IF NOT EXISTS ix_cards_sim ON cards(sim_group)")
    if "liked" not in cols:
        con.execute("ALTER TABLE cards ADD COLUMN liked INTEGER DEFAULT 0")     # 좋아요(원해요) ♥
    if "user_order" not in cols:
        con.execute("ALTER TABLE cards ADD COLUMN user_order REAL")        # 사용자 정렬 순서
    con.execute("CREATE INDEX IF NOT EXISTS ix_cards_info ON cards(info_key)")
    con.execute("CREATE INDEX IF NOT EXISTS ix_info_codi ON card_info(codi)")
    if "qr" not in cols:
        con.execute("ALTER TABLE cards ADD COLUMN qr TEXT")                # QR 사진 파일명 (QR사진 폴더)
    con.execute("CREATE INDEX IF NOT EXISTS ix_cards_user ON cards(user_order)")
    fill_user_order(con)
    con.commit()
    con.close()


def fill_user_order(con):
    """사용자 정렬 순서가 없는 카드는 번호 순서대로 맨 뒤에 붙임"""
    rows = con.execute("SELECT id FROM cards WHERE user_order IS NULL ORDER BY sort_key, lang, id").fetchall()
    if not rows:
        return
    mx = con.execute("SELECT COALESCE(MAX(user_order), 0) FROM cards").fetchone()[0] or 0
    con.executemany("UPDATE cards SET user_order=? WHERE id=?",
                    [(mx + 1024.0 * (n + 1), r[0]) for n, r in enumerate(rows)])


def get_grades(con):
    row = con.execute("SELECT value FROM settings WHERE key='grades'").fetchone()
    s = row["value"] if row else DEFAULT_GRADES
    return [g.strip().upper() for g in re.split(r"[,\n]+", s) if g.strip()]


# ---------------------------------------------------------------- 파일명 분석
RE_KANA = re.compile(r"[\u3040-\u30FF\u31F0-\u31FF\uFF66-\uFF9F]")
RE_HANGUL = re.compile(r"[\uAC00-\uD7A3\u1100-\u11FF\u3130-\u318F]")
RE_KANJI = re.compile(r"[\u4E00-\u9FFF]")
RE_SETNUM = re.compile(  # OP01-001, 15PV-005, 1506-60, 1505-CP11, PC-121, LIVE-003
    r"(?<![A-Za-z0-9])([A-Za-z0-9]{1,8})\s*[-－‐]\s*([A-Za-z]{0,3}\d{1,4}[A-Za-z]?)(?![A-Za-z0-9])")
RE_FOLDER_KR = re.compile(r"한국|한글|국내|kor|(?<![a-z])kr(?![a-z])", re.I)
RE_FOLDER_JP = re.compile(r"일본|日本|和|jpn|japan|(?<![a-z])jp(?![a-z])", re.I)
RE_NUM = re.compile(r"(?:No\.?|#|第)?\s*(?<![0-9])(\d{2,4})(?![0-9])", re.I)
RE_SPLIT = re.compile(r"[\s_\-\[\]\(\)【】「」『』（）〔〕《》<>{}.,·・／]+")
BAD_CHARS = re.compile(r'[\\/:*?"<>|\x00-\x1f]')


def nfc(s):
    return unicodedata.normalize("NFC", s or "")


def detect_lang(s):
    if RE_KANA.search(s):
        return "일본어"
    if RE_HANGUL.search(s):
        return "한국어"
    if RE_KANJI.search(s):
        return "일본어"
    return "기타"


def make_sort_key(card_no):
    if not card_no:
        return "~"  # 번호 없는 카드는 맨 뒤
    return re.sub(r"\d+", lambda m: m.group().zfill(6), card_no.upper())


def lang_from_folder(hint):
    """파일 이름에 한글·가나가 없을 때 폴더 이름(한국판/일본판/KR/JP 등)으로 언어 추정"""
    for part in reversed(re.split(r"[\\/]", nfc(hint or ""))[:-1] if hint else []):
        if RE_FOLDER_JP.search(part):
            return "일본어"
        if RE_FOLDER_KR.search(part):
            return "한국어"
    return "기타"


def parse_name(fname, grades, hint=""):
    base = nfc(Path(fname).stem)
    lang = detect_lang(base)
    if lang == "기타" and hint:
        lang = lang_from_folder(hint)
    r = {"lang": lang, "set_code": "", "card_no": "", "grade": "", "title": ""}
    rest = base
    m = RE_SETNUM.search(rest)
    if m:
        r["set_code"] = m.group(1).upper()
        r["card_no"] = r["set_code"] + "-" + m.group(2).upper()
        rest = rest.replace(m.group(0), " ", 1)
    else:
        m = RE_NUM.search(rest)
        if m:
            r["card_no"] = m.group(1)
            rest = rest.replace(m.group(0), " ", 1)
    toks = [t for t in RE_SPLIT.split(rest) if t]
    for i in range(len(toks) - 1, -1, -1):
        if toks[i].upper() in grades:
            r["grade"] = toks[i].upper()
            del toks[i]
            break
    r["title"] = " ".join(toks).strip()
    r["sort_key"] = make_sort_key(r["card_no"])
    return r


def safe_part(s, empty):
    s = BAD_CHARS.sub("_", s or "").strip(" .")
    return s or empty


# ---------------------------------------------------------------- 등록 / 삭제
def abs_path(row):
    p = row["file_path"]
    if row["owned"]:
        return STORE.joinpath(*[x for x in re.split(r"[\\/]", p) if x])
    return Path(p)


def store_target(meta, fname):
    sub = STORE / safe_part(meta["lang"], "기타") / safe_part(meta["grade"], "등급없음")
    sub.mkdir(parents=True, exist_ok=True)
    name = safe_part(nfc(Path(fname).name), "image.png")
    stem, ext = Path(name).stem, Path(name).suffix
    target, i = sub / name, 2
    while target.exists():
        target = sub / ("%s (%d)%s" % (stem, i, ext))
        i += 1
    return target


def apply_meta(meta, over):
    """CSV 등에서 받은 값으로 자동 분석값을 덮어씀 (빈 값은 무시)"""
    over = over or {}
    for k in ("lang", "set_code", "card_no", "grade", "title", "memo"):
        v = nfc(str(over.get(k) or "")).strip()
        if v:
            meta[k] = v.upper() if k in ("grade", "card_no", "set_code") else v
    if over.get("card_no") and not over.get("set_code"):
        meta["set_code"] = meta["card_no"].split("-")[0] if "-" in meta["card_no"] else ""
    meta["sort_key"] = make_sort_key(meta["card_no"])
    return meta


def register(con, fname, data=None, src_path=None, copy=True, grades=None, meta_over=None, dup="skip"):
    """이미지 1장 등록. data(bytes) 또는 src_path 중 하나 사용.
    dup: skip(중복 건너뜀) / update(중복이면 분류 정보만 갱신). 반환: (상태, id)"""
    fname = nfc(fname)
    if Path(fname).suffix.lower() not in IMG_EXT:
        return "skip", None
    if data is None:
        data = Path(src_path).read_bytes()
    sha = hashlib.sha256(data).hexdigest()
    hint = str(src_path) if src_path is not None else (meta_over or {}).get("_hint", "")
    meta = apply_meta(parse_name(fname, grades or get_grades(con), hint), meta_over)
    row = con.execute("SELECT id FROM cards WHERE sha256=?", (sha,)).fetchone()
    if row:
        if dup == "update":
            memo = meta.get("memo", "")
            con.execute("UPDATE cards SET lang=?, set_code=?, card_no=?, grade=?, title=?, sort_key=?, "
                        "memo=CASE WHEN ?<>'' THEN ? ELSE memo END, updated_at=datetime('now','localtime') WHERE id=?",
                        (meta["lang"], meta["set_code"], meta["card_no"], meta["grade"], meta["title"],
                         meta["sort_key"], memo, memo, row["id"]))
            return "updated", row["id"]
        return "dup", row["id"]
    if copy or src_path is None:
        target = store_target(meta, fname)
        target.write_bytes(data)
        fpath, owned = str(target.relative_to(STORE)), 1
    else:
        fpath, owned = str(Path(src_path).resolve()), 0
    cur = con.execute(
        "INSERT INTO cards(file_name, lang, set_code, card_no, grade, title, memo, sort_key, file_path, owned, sha256, size,"
        " user_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?, (SELECT COALESCE(MAX(user_order),0)+1024 FROM cards))",
        (fname, meta["lang"], meta["set_code"], meta["card_no"], meta["grade"], meta["title"], meta.get("memo", ""),
         meta["sort_key"], fpath, owned, sha, len(data)))
    link_one(con, cur.lastrowid, fname)
    return "added", cur.lastrowid


def delete_cards(con, ids):
    n = 0
    for cid in ids:
        row = con.execute("SELECT * FROM cards WHERE id=?", (int(cid),)).fetchone()
        if not row:
            continue
        if row["owned"]:
            p = abs_path(row)
            try:
                p.unlink()
                # 비어 있는 폴더 정리
                for d in (p.parent, p.parent.parent):
                    if d != STORE and d.exists() and not any(d.iterdir()):
                        d.rmdir()
            except OSError:
                pass
        remove_qr(con, row["id"])
        con.execute("DELETE FROM cards WHERE id=?", (row["id"],))
        n += 1
    con.commit()
    return n


