def temp_dir():
    d = DATA_DIR / "_임시업로드"
    d.mkdir(parents=True, exist_ok=True)
    return d


def zip_member_name(info):
    """한국/일본 Windows에서 만든 ZIP의 깨진 파일명 복원"""
    if info.flag_bits & 0x800:
        return info.filename
    try:
        raw = info.filename.encode("cp437")
    except UnicodeEncodeError:
        return info.filename
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError:
        pass

    def score(t):  # 자연스러운 글자가 많을수록 높은 점수 (자주 쓰는 한글 2,350자·가나·한자)
        sc = 0
        for ch in t:
            o = ord(ch)
            if o < 128:
                continue
            if 0xFF61 <= o <= 0xFF9F:          # 반각 가나: 한글 바이트를 cp932로 잘못 읽을 때 나옴
                sc -= 2
            elif 0x3040 <= o <= 0x30FF:          # 히라가나·가타카나
                sc += 2
            elif 0xAC00 <= o <= 0xD7A3:          # 한글: KS X 1001 기본 글자만 가산
                sc += 2 if len(ch.encode("euc-kr", "ignore")) == 2 else -2
            elif 0x4E00 <= o <= 0x9FFF:
                sc += 1
            else:
                sc -= 1
        return sc

    cands = []
    for enc in ("cp949", "cp932"):
        try:
            cands.append(raw.decode(enc))
        except UnicodeDecodeError:
            pass
    return max(cands, key=score) if cands else info.filename


COLOR_NAMES = ["빨강", "주황", "노랑", "초록", "하늘", "파랑", "보라", "핑크", "갈색", "흰색", "회색", "검정"]
FEAT_VER = 1        # 이미지 분석 방식 버전 (바뀌면 다시 분석)

INFO_EXT = {".txt", ".tsv", ".csv"}
# 프로그램이 만든 목록·로그 파일은 설명 파일로 보지 않음
RE_NOT_INFO = re.compile(r"^(카드목록|등록결과.*|대량등록_양식|이미지없는카드목록)\.(csv|txt)$")


def is_info_name(name):
    return Path(name).suffix.lower() in INFO_EXT and not RE_NOT_INFO.match(nfc(Path(name).name)) \
        and not Path(name).name.startswith("._")


def collect_paths(paths, notes, infos=None):
    """폴더·이미지·ZIP 경로 목록 → 작업 목록 (infos: 함께 들어 있는 번호 설명 파일 목록)"""
    tasks = []

    def add_file(f):
        ext = f.suffix.lower()
        if infos is not None and is_info_name(f.name):
            infos.append({"path": f, "show": str(f)})
            return
        if ext in IMG_EXT:
            if STORE in f.resolve().parents:
                return
            tasks.append({"name": nfc(f.name), "path": f, "show": str(f)})
        elif ext == ".zip":
            try:
                with zipfile.ZipFile(str(f)) as z:
                    for info in z.infolist():
                        if info.is_dir():
                            continue
                        real = zip_member_name(info)
                        if infos is not None and is_info_name(real):
                            infos.append({"zip": f, "member": info.filename, "show": "%s ▸ %s" % (f.name, nfc(real))})
                            continue
                        if Path(real).suffix.lower() in IMG_EXT and not Path(real).name.startswith("._"):
                            tasks.append({"name": nfc(Path(real).name), "zip": f, "member": info.filename,
                                          "show": "%s ▸ %s" % (f.name, nfc(real))})
            except Exception as e:  # noqa  손상된 ZIP 등은 오류로 기록하고 계속 진행
                notes.append("ZIP 파일을 열 수 없음: %s (%s)" % (f, e))

    for raw in paths:
        raw = str(raw).strip().strip('"').strip()
        if not raw:
            continue
        p = Path(raw)
        if p.is_dir():
            for f in sorted(p.rglob("*")):
                if f.is_file():
                    add_file(f)
        elif p.is_file():
            add_file(p)
        else:
            notes.append("경로를 찾을 수 없음: %s" % raw)
    return tasks


def collect_csv(csv_path, notes):
    """CSV 목록(파일경로 + 카드번호·등급·카드명 등) → 작업 목록"""
    csv_path = Path(str(csv_path).strip().strip('"'))
    if not csv_path.is_file():
        notes.append("CSV 파일을 찾을 수 없음: %s" % csv_path)
        return []
    raw = csv_path.read_bytes()
    for enc in ("utf-8-sig", "cp949", "cp932"):
        try:
            text = raw.decode(enc)
            break
        except UnicodeDecodeError:
            continue
    else:
        notes.append("CSV 인코딩을 알 수 없음: %s" % csv_path)
        return []
    rd = csv.DictReader(io.StringIO(text))
    colmap = {}
    for h in rd.fieldnames or []:
        key = nfc(h).strip().lower().replace(" ", "")
        for k, names in CSV_COLS.items():
            if key in [n.lower() for n in names] and k not in colmap:
                colmap[k] = h
    if "path" not in colmap:
        notes.append("CSV 첫 줄에 '파일경로' 열이 없습니다. (현재 열: %s)" % ", ".join(rd.fieldnames or []))
        return []
    base = csv_path.parent
    tasks = []
    for n, row in enumerate(rd, 2):
        v = (row.get(colmap["path"]) or "").strip().strip('"')
        if not v:
            continue
        p = Path(v)
        if not p.is_absolute():
            p = base / p
        if not p.is_file():
            notes.append("%d행: 파일 없음 %s" % (n, v))
            continue
        meta = {k: (row.get(col) or "") for k, col in colmap.items() if k != "path"}
        tasks.append({"name": nfc(p.name), "path": p, "meta": meta, "show": str(p)})
    return tasks


def run_job(paths, csv_file, copy, dup, cleanup, echo=False):
    """백그라운드(또는 명령줄)에서 실행되는 대량 등록"""
    con = db()
    zips, log, notes = {}, [], []
    t_start = time.time()
    try:
        with JOB_LOCK:
            JOB.update(phase="scan", msg="파일 목록 만드는 중")
        infos = []
        tasks = collect_paths(paths or [], notes, infos)
        if csv_file:
            tasks += collect_csv(csv_file, notes)
        for n in notes:
            log.append(["오류", n, "", ""])
        # 1) 이미지 번호 설명 파일 → card_info (이미지보다 먼저 저장해야 등록하면서 바로 연결됨)
        info_msgs = []
        for inf in infos:
            with JOB_LOCK:
                JOB.update(msg="번호 설명 파일 저장 중", current=inf["show"])
            try:
                if "zip" in inf:
                    with zipfile.ZipFile(str(inf["zip"])) as zf:
                        raw = zf.read(inf["member"])
                else:
                    raw = Path(inf["path"]).read_bytes()
                st = import_info(con, raw)
                m = "%d행 저장 (신규 %d, 갱신 %d)" % (st["rows"], st["inserted"], st["updated"])
                log.append(["번호 설명 파일", inf["show"], m, ""])
                info_msgs.append("%s: %s" % (Path(inf["show"].split(" ▸ ")[-1]).name, m))
                with JOB_LOCK:
                    JOB["info_rows"] += st["inserted"] + st["updated"]
            except ValueError as e:      # 번호 열이 없는 텍스트 → 설명 파일이 아님
                log.append(["설명 파일 아님(건너뜀)", inf["show"], str(e), ""])
            except Exception as e:  # noqa
                log.append(["오류", inf["show"], str(e), ""])
                notes.append("%s: %s" % (inf["show"], e))
        with JOB_LOCK:
            JOB["info_msg"] = " / ".join(info_msgs)
        if echo and info_msgs:
            print("번호 설명 파일: " + " / ".join(info_msgs))
        grades = get_grades(con)
        with JOB_LOCK:
            JOB.update(phase="run", total=len(tasks), msg="등록 중", started=time.time())
            JOB["error"] += len(notes)
            JOB["errors"] += notes[:50]
        if echo:
            print("등록 대상 %d장" % len(tasks))
            for n in notes:
                print("  ! " + n)
        for i, t in enumerate(tasks, 1):
            if JOB["cancel"]:
                with JOB_LOCK:
                    JOB["msg"] = "사용자가 중단함"
                break
            with JOB_LOCK:
                JOB["current"] = t["show"]
            err = ""
            try:
                if "zip" in t:
                    z = zips.get(t["zip"])
                    if z is None:
                        z = zips[t["zip"]] = zipfile.ZipFile(str(t["zip"]))
                    st, cid = register(con, t["name"], data=z.read(t["member"]), copy=True, grades=grades,
                                       meta_over=dict(t.get("meta") or {}, _hint=t["show"].replace(" ▸ ", "/")), dup=dup)
                else:
                    st, cid = register(con, t["name"], src_path=t["path"], copy=copy,
                                       grades=grades, meta_over=t.get("meta"), dup=dup)
            except Exception as e:  # noqa
                st, cid, err = "error", None, str(e)
            log.append([STATUS_KO[st], t["show"], err, cid or ""])
            with JOB_LOCK:
                JOB["done"] = i
                JOB[st] += 1
                if err and len(JOB["errors"]) < 50:
                    JOB["errors"].append("%s: %s" % (t["name"], err))
            if i % 200 == 0:
                con.commit()
                if echo:
                    el = time.time() - t_start
                    print("  %d / %d (%.0f장/초)" % (i, len(tasks), i / el if el else 0))
        if infos or tasks:
            linked, total_cards = link_all(con)
            with JOB_LOCK:
                JOB["linked"] = linked
        con.commit()
        with JOB_LOCK:
            if JOB["msg"] == "등록 중":
                JOB["msg"] = "완료"
    except Exception as e:  # noqa
        traceback.print_exc()
        with JOB_LOCK:
            JOB["msg"] = "오류: %s" % e
    finally:
        con.close()
        for z in zips.values():
            z.close()
        tmp = temp_dir().resolve()
        for c in cleanup or []:
            try:
                cp = Path(c).resolve()
                if tmp in cp.parents:
                    cp.unlink()
            except OSError:
                pass
        # 결과 로그 저장
        logdir = DATA_DIR / "등록결과"
        logdir.mkdir(parents=True, exist_ok=True)
        lf = logdir / ("등록결과_%s.csv" % time.strftime("%Y%m%d_%H%M%S"))
        with open(str(lf), "w", newline="", encoding="utf-8-sig") as f:
            w = csv.writer(f)
            w.writerow(["결과", "파일", "메시지", "카드ID"])
            w.writerows(log)
        with JOB_LOCK:
            JOB.update(running=False, phase="done", current="", finished=time.time(), log_file=str(lf))


def start_job(paths, csv_file, copy, dup, cleanup):
    with JOB_LOCK:
        if JOB["running"]:
            return False
        JOB.update(running=True, cancel=False, phase="scan", total=0, done=0, added=0, dup=0, updated=0,
                   info_rows=0, info_msg="", linked=0,
                   skip=0, error=0, current="", msg="준비 중", errors=[], started=time.time(), finished=0,
                   log_file="")
    threading.Thread(target=run_job, args=(paths, csv_file, copy, dup, cleanup), daemon=True).start()
    return True


def preview(paths, csv_file, limit=300):
    notes, infos = [], []
    tasks = collect_paths(paths or [], notes, infos)
    if csv_file:
        tasks += collect_csv(csv_file, notes)
    con = db()
    grades = get_grades(con)
    con.close()
    samples = []
    for t in tasks[:limit]:
        m = apply_meta(parse_name(t["name"], grades), t.get("meta"))
        samples.append({"show": t["show"], "lang": m["lang"], "card_no": m["card_no"], "grade": m["grade"],
                        "title": m["title"]})
    return {"count": len(tasks), "zip": sum(1 for t in tasks if "zip" in t),
            "csv": sum(1 for t in tasks if "meta" in t), "notes": notes[:100], "samples": samples,
            "infos": [i["show"] for i in infos]}


# ---------------------------------------------------------------- 카드 정보 (텍스트 파일) · 이미지 연결
RE_SUFFIX = re.compile(r"^(.+?)_(\d+)$")


def info_key(s):
    """번호 비교용: 공백 제거 + 대문자 ("14 01-01" == "1401-01")"""
    return re.sub(r"\s+", "", nfc(s or "")).upper()


def stem_key(fname):
    return info_key(Path(nfc(fname)).stem)


def link_one(con, cid, fname=None):
    """카드 1장을 카드 정보와 연결 (번호 = 이미지 파일명)"""
    if fname is None:
        r = con.execute("SELECT file_name, info_manual FROM cards WHERE id=?", (cid,)).fetchone()
        if not r or r["info_manual"]:
            return
        fname = r["file_name"]
    k = stem_key(fname)
    if con.execute("SELECT 1 FROM card_info WHERE no_key=?", (k,)).fetchone():
        con.execute("UPDATE cards SET info_key=? WHERE id=?", (k, cid))
        return
    m = RE_SUFFIX.match(k)
    target = None
    if m:   # PC-086_70802 → PC-086, PC-086-2, PC-086-3 … 중 아직 이미지가 없는 번호
        base = m.group(1)
        cands = [base] + ["%s-%d" % (base, n) for n in range(2, 10)]
        exist = [c for c in cands if con.execute("SELECT 1 FROM card_info WHERE no_key=?", (c,)).fetchone()]
        for c in exist:
            if not con.execute("SELECT 1 FROM cards WHERE info_key=? AND id<>?", (c, cid)).fetchone():
                target = c
                break
        if target is None and exist:
            target = exist[0]          # 같은 카드의 다른 이미지
    con.execute("UPDATE cards SET info_key=? WHERE id=?", (target, cid))


def link_all(con):
    """모든 카드를 카드 정보와 다시 연결 (직접 연결한 카드는 그대로)"""
    keys = {r[0] for r in con.execute("SELECT no_key FROM card_info")}
    cards = con.execute("SELECT id, file_name, info_manual, info_key FROM cards ORDER BY id").fetchall()
    used = {r["info_key"] for r in cards if r["info_manual"] and r["info_key"]}
    result, groups = {}, {}
    for r in cards:
        if r["info_manual"]:
            continue
        k = stem_key(r["file_name"])
        if k in keys:
            result[r["id"]] = k
            used.add(k)
        else:
            m = RE_SUFFIX.match(k)
            if m:
                groups.setdefault(m.group(1), []).append((int(m.group(2)), r["id"]))
            else:
                result[r["id"]] = None
    for base, items in groups.items():
        cands = [c for c in [base] + ["%s-%d" % (base, n) for n in range(2, 10)] if c in keys]
        free = [c for c in cands if c not in used]
        for _, cid in sorted(items):
            if free:
                result[cid] = free.pop(0)
                used.add(result[cid])
            else:
                result[cid] = cands[0] if cands else None
    con.executemany("UPDATE cards SET info_key=? WHERE id=?", [(v, k) for k, v in result.items()])
    linked = sum(1 for v in result.values() if v) + sum(1 for r in cards if r["info_manual"] and r["info_key"])
    return linked, len(cards)


def decode_text(raw):
    for enc in ("utf-8-sig", "cp949", "cp932", "utf-16"):
        try:
            return raw.decode(enc)
        except UnicodeDecodeError:
            continue
    return raw.decode("utf-8", "replace")


def import_info(con, raw, replace_all=False):
    """텍스트(탭 구분 TXT 또는 CSV) → card_info 테이블. 첫 줄은 열 이름"""
    text = decode_text(raw).replace("\r\n", "\n").replace("\r", "\n")
    lines = [l for l in text.split("\n") if l.strip()]
    if not lines:
        raise ValueError("파일이 비어 있습니다.")
    delim = "\t" if "\t" in lines[0] else ("," if "," in lines[0] else "\t")
    rd = csv.reader(lines, delimiter=delim, quoting=csv.QUOTE_NONE if delim == "\t" else csv.QUOTE_MINIMAL)
    header = [nfc(h).strip() for h in next(rd)]
    colmap, extra_cols = {}, []
    for idx, h in enumerate(header):
        hk = h.replace(" ", "").lower()
        for f, names in INFO_ALIASES.items():
            if f not in colmap and hk in [n.replace(" ", "").lower() for n in names]:
                colmap[f] = idx
                break
        else:
            extra_cols.append((idx, h))
    if "no" not in colmap:
        raise ValueError("첫 줄에 '번호' 열이 없습니다. (현재 열: %s)" % ", ".join(header))
    st = {"rows": 0, "inserted": 0, "updated": 0, "skipped": 0, "dup_in_file": 0, "deleted": 0,
          "columns": [INFO_LABELS[INFO_FIELDS.index(f)] for f in INFO_FIELDS if f in colmap],
          "extra": [h for _, h in extra_cols if h]}
    seen = set()
    for row in rd:
        st["rows"] += 1
        get = lambda f: nfc(row[colmap[f]]).strip() if f in colmap and colmap[f] < len(row) else ""
        no = get("no")
        if not no:
            st["skipped"] += 1
            continue
        k = info_key(no)
        if k in seen:
            st["dup_in_file"] += 1
        seen.add(k)
        vals = {f: get(f) for f in INFO_FIELDS}
        ex = {h: nfc(row[i]).strip() for i, h in extra_cols if h and i < len(row) and row[i].strip()}
        vals["extra"] = json.dumps(ex, ensure_ascii=False) if ex else ""
        old = con.execute("SELECT 1 FROM card_info WHERE no_key=?", (k,)).fetchone()
        cols = INFO_FIELDS + ["extra"]
        if old:
            # 텍스트에 없는 열이나 빈 칸은 기존 값(예: 직접 입력한 수량·메모)을 지우지 않음
            upd = [c for c in cols if c == "no" or c in colmap or (c == "extra" and extra_cols)]
            con.execute("UPDATE card_info SET %s, updated_at=datetime('now','localtime') WHERE no_key=?"
                        % ", ".join("%s=CASE WHEN ?='' THEN %s ELSE ? END" % (c, c) for c in upd),
                        [x for c in upd for x in (vals[c], vals[c])] + [k])
            st["updated"] += 1
        else:
            con.execute("INSERT INTO card_info(no_key, %s) VALUES(?, %s)" % (", ".join(cols), ",".join("?" * len(cols))),
                        [k] + [vals[c] for c in cols])
            st["inserted"] += 1
    if replace_all and seen:
        old_keys = [r[0] for r in con.execute("SELECT no_key FROM card_info")]
        gone = [k for k in old_keys if k not in seen]
        con.executemany("DELETE FROM card_info WHERE no_key=?", [(k,) for k in gone])
        st["deleted"] = len(gone)
    linked, total = link_all(con)
    con.commit()
    st["cards"] = total
    st["linked"] = linked
    st["unlinked_cards"] = [r[0] for r in con.execute(
        "SELECT c.file_name" + FROMX + " WHERE i.no_key IS NULL ORDER BY c.sort_key LIMIT 50")]
    st["unlinked_count"] = con.execute("SELECT COUNT(*)" + FROMX + " WHERE i.no_key IS NULL").fetchone()[0]
    st["no_image"] = [r[0] for r in con.execute(
        "SELECT no FROM card_info WHERE no_key NOT IN (SELECT info_key FROM cards WHERE info_key IS NOT NULL) "
        "ORDER BY no LIMIT 50")]
    st["no_image_count"] = con.execute(
        "SELECT COUNT(*) FROM card_info WHERE no_key NOT IN (SELECT info_key FROM cards WHERE info_key IS NOT NULL)"
    ).fetchone()[0]
    st["info_total"] = con.execute("SELECT COUNT(*) FROM card_info").fetchone()[0]
    return st


# ---------------------------------------------------------------- 사용자 정렬
def renumber_user_order(con):
    rows = con.execute("SELECT id FROM cards ORDER BY user_order, id").fetchall()
    con.executemany("UPDATE cards SET user_order=? WHERE id=?", [(1024.0 * (n + 1), r[0]) for n, r in enumerate(rows)])


def reorder(con, ids, qs, target_id=None, side="before", position=None):
    """현재 목록(검색·필터 적용)에서 ids 카드를 target 카드 앞/뒤 또는 position번째로 옮김"""
    fill_user_order(con)
    ids = [int(x) for x in ids]
    idset = set(ids)
    where, p = build_where(qs)
    seq = [r[0] for r in con.execute("SELECT c.id" + FROMX + where + " ORDER BY c.user_order, c.id", p)]
    moving = [i for i in seq if i in idset] + [i for i in ids if i not in set(seq)]
    rest = [i for i in seq if i not in idset]
    if position is not None:
        idx = max(0, min(len(rest), int(position) - 1))
    else:
        target_id = int(target_id)
        if target_id in idset or target_id not in rest:
            return False
        idx = rest.index(target_id) + (1 if side == "after" else 0)
    for attempt in range(2):
        order = dict(con.execute("SELECT id, user_order FROM cards").fetchall())
        prev = order[rest[idx - 1]] if idx > 0 else None
        nxt = order[rest[idx]] if idx < len(rest) else None
        k = len(moving)
        if prev is None and nxt is None:
            return False
        lo = prev if prev is not None else nxt - 1024.0 * (k + 1)
        hi = nxt if nxt is not None else prev + 1024.0 * (k + 1)
        step = (hi - lo) / (k + 1)
        if step > 1e-6 or attempt == 1:
            con.executemany("UPDATE cards SET user_order=? WHERE id=?",
                            [(lo + step * (j + 1), cid) for j, cid in enumerate(moving)])
            con.commit()
            return True
        renumber_user_order(con)   # 간격이 너무 좁아지면 전체 번호를 다시 매김
    return True


def arrange_user_order(con, qs, mode):
    """사용자 정렬 순서를 색상별/이미지별/번호순으로 한 번에 다시 매김.
    검색·필터가 걸려 있으면 그 카드들이 차지하던 자리 안에서만 바꾸고, 나머지 카드 순서는 그대로 둔다."""
    fill_user_order(con)
    where, p = build_where(qs)
    rows = con.execute("SELECT c.id, c.user_order" + FROMX + where, p).fetchall()
    if not rows:
        return 0
    color_case = "CASE c.color_main " + " ".join("WHEN '%s' THEN %d" % (n, i) for i, n in enumerate(COLOR_NAMES)) + " ELSE 99 END"
    group_first = "COALESCE((SELECT MIN(c2.sort_key) FROM cards c2 WHERE c2.sim_group=c.sim_group), c.sort_key)"
    order = {
        # 색상별: 대표 색 순서 → 같은 색 안에서는 비슷한 이미지끼리 → 번호
        "color": color_case + ", " + group_first + ", c.sim_group, c.sort_key, c.id",
        # 이미지별: 번호 순서를 유지하되 비슷한 이미지는 묶음의 첫 카드 자리에 모아서
        "similar": group_first + ", c.sim_group, c.sort_key, c.id",
        "codi": CODI_ORDER,
        "num": "c.sort_key, c.lang, c.id",
    }[mode]
    ids = [r[0] for r in con.execute("SELECT c.id" + FROMX + where + " ORDER BY " + order, p)]
    slots = sorted(r[1] for r in rows)
    # 되돌리기용 백업 (마지막 1회)
    backup = {str(r[0]): r[1] for r in con.execute("SELECT id, user_order FROM cards")}
    con.execute("INSERT OR REPLACE INTO settings(key, value) VALUES('user_order_backup', ?)", (json.dumps(backup),))
    con.executemany("UPDATE cards SET user_order=? WHERE id=?", list(zip(slots, ids)))
    con.commit()
    return len(ids)


def adopt_sort_order(con, qs):
    """지금 화면의 정렬(코디별·번호순 등)을 사용자 정렬 순서로 가져옴 — 정렬과 상관없이 끌어서 옮길 수 있게.
    검색·필터가 걸려 있으면 그 카드들이 차지하던 자리 안에서만 바꿈. 되돌리기용 백업을 남김."""
    s = qs.get("sort", ["user"])[0]
    if s == "user":
        return False
    fill_user_order(con)
    where, p = build_where(qs)
    rows = con.execute("SELECT c.id, c.user_order" + FROMX + where, p).fetchall()
    if not rows:
        return False
    ids = [r[0] for r in con.execute("SELECT c.id" + FROMX + where + order_by(con, qs) + ", c.id", p)]
    slots = sorted(r[1] for r in rows)
    backup = {str(r[0]): r[1] for r in con.execute("SELECT id, user_order FROM cards")}
    con.execute("INSERT OR REPLACE INTO settings(key, value) VALUES('user_order_backup', ?)", (json.dumps(backup),))
    con.executemany("UPDATE cards SET user_order=? WHERE id=?", list(zip(slots, ids)))
    con.commit()
    return True


def user_position(con, cid, qs):
    where, p = build_where(qs)
    seq = [r[0] for r in con.execute("SELECT c.id" + FROMX + where + " ORDER BY c.user_order, c.id", p)]
    return (seq.index(cid) + 1) if cid in seq else 0, len(seq)


# ---------------------------------------------------------------- 조회
SORTS = {
    "num": "c.sort_key, c.lang, c.id",
    "title": "CASE WHEN COALESCE(i.name_ko,'')='' THEN 1 ELSE 0 END, COALESCE(NULLIF(i.name_ko,''), c.title) COLLATE NOCASE, c.sort_key",
    "lang": "c.lang, c.sort_key",
    "new": "c.id DESC",
    "file": "c.file_name COLLATE NOCASE",
    "user": "c.user_order, c.id",
    "similar": "c.sim_group IS NULL, c.sim_group, c.sort_key, c.id",
    "color": "CASE c.color_main " + " ".join("WHEN '%s' THEN %d" % (n, i) for i, n in enumerate(
        ["빨강", "주황", "노랑", "초록", "하늘", "파랑", "보라", "핑크", "갈색", "흰색", "회색", "검정"])) +
             " ELSE 99 END, c.sort_key, c.id",
}
FILTERS = (("lang", "c.lang"), ("grade", EFF_GRADE), ("set", "c.set_code"), ("tan", "COALESCE(i.tan,'')"),
           ("type", "COALESCE(i.type,'')"), ("brand", "COALESCE(i.brand,'')"), ("part", "COALESCE(i.part,'')"),
           ("source", "COALESCE(i.source,'')"), ("codi", "COALESCE(i.codi,'')"))
# 코디별: 탄 순서 → 같은 탄 안에서는 코디의 첫 카드(가장 앞 번호) 자리에 그 코디를 모아서
#         (코디 없는 카드는 자기 번호 자리) → 같은 코디 안에서 상의·하의·원피스·슈즈·악세 → 번호
# 번호 = 카드 정보의 번호(= 이미지 파일명), 숫자 자리수를 맞춰 비교
NUM_KEY = "num_key(COALESCE(NULLIF(i.no,''), c.card_no))"
CODI_FIRST = ("CASE WHEN COALESCE(i.codi,'')='' THEN " + NUM_KEY + " ELSE "
              "(SELECT MIN(num_key(i2.no)) FROM card_info i2 "
              "WHERE i2.codi=i.codi AND COALESCE(i2.tan,'')=COALESCE(i.tan,'')) END")
CODI_ORDER = ("tan_rank(i.tan), " + CODI_FIRST + ", CASE WHEN COALESCE(i.codi,'')='' THEN 1 ELSE 0 END, i.codi, "
              "part_rank(i.part), " + NUM_KEY + ", c.lang, c.id")
SORTS["codi"] = CODI_ORDER


def build_where(qs):
    w, p = [], []
    q = nfc(qs.get("q", [""])[0]).strip()
    for word in q.split():
        w.append("(c.title LIKE ? OR c.file_name LIKE ? OR c.card_no LIKE ? OR c.set_code LIKE ? OR c.memo LIKE ? "
                 "OR i.no LIKE ? OR i.name_ko LIKE ? OR i.name_jp LIKE ? OR i.brand LIKE ? OR i.tan LIKE ? OR i.memo LIKE ? "
                 "OR REPLACE(i.no,' ','') LIKE ?)")
        p += ["%" + word + "%"] * 12
    for key, col in FILTERS:
        vals = [v for v in qs.get(key, []) if v != ""]
        if vals:
            vals = ["" if v == "(없음)" else v for v in vals]
            w.append("%s IN (%s)" % (col, ",".join("?" * len(vals))))
            p += vals
    if qs.get("nonum", [""])[0] == "1":
        w.append("c.card_no = ''")
    if qs.get("nograde", [""])[0] == "1":
        w.append(EFF_GRADE + " = ''")
    cols_f = [v for v in qs.get("color", []) if v]
    if cols_f:   # 색상: 대표 색 목록(15% 이상 차지하는 색)에 들어 있는 카드
        w.append("(" + " OR ".join("(',' || COALESCE(c.colors,'') || ',') LIKE ?" for _ in cols_f) + ")")
        p += ["%," + v + ",%" for v in cols_f]
    if qs.get("colormain", [""])[0] == "1" and cols_f:
        w.append("c.color_main IN (%s)" % ",".join("?" * len(cols_f)))
        p += cols_f
    if qs.get("similar", [""])[0] == "1":
        w.append("c.sim_group IS NOT NULL")
    if qs.get("liked", [""])[0] == "1":
        w.append("c.liked = 1")
    if qs.get("noinfo", [""])[0] == "1":
        w.append("i.no_key IS NULL")
    if qs.get("dual", [""])[0] == "1":
        w.append("c.card_no IN (SELECT card_no FROM cards WHERE card_no<>'' GROUP BY card_no "
                 "HAVING SUM(lang='한국어')>0 AND SUM(lang='일본어')>0)")
    return (" WHERE " + " AND ".join(w)) if w else "", p


def order_by(con, qs):
    s = qs.get("sort", ["num"])[0]
    if s == "grade":
        grades = get_grades(con)
        case = "CASE " + EFF_GRADE + " " + " ".join("WHEN '%s' THEN %d" % (g.replace("'", "''"), i)
                                                   for i, g in enumerate(grades)) + " ELSE 999 END"
        return " ORDER BY %s, c.sort_key" % case
    return " ORDER BY " + SORTS.get(s, SORTS["num"])


def row_dict(r):
    d = dict(r)
    d.pop("sha256", None)
    return d


# ---------------------------------------------------------------- 다운로드 (ZIP 스트리밍)
class _StreamOut:
    """소켓으로 바로 내보내는 쓰기 전용 스트림 (임시 파일 없이 ZIP 전송)"""
    def __init__(self, w):
        self.w = w

    def write(self, b):
        self.w.write(b)
        return len(b)

    def flush(self):
        self.w.flush()


def stream_zip(wfile, rows):
    used, listing = set(), []
    with zipfile.ZipFile(_StreamOut(wfile), "w", zipfile.ZIP_STORED, allowZip64=True) as z:
        for r in rows:
            src = abs_path(r)
            arc = "%s/%s/%s" % (safe_part(r["lang"], "기타"), safe_part(r["eff_grade"], "등급없음"),
                                safe_part(r["file_name"], "image.png"))
            stem, ext, i = arc[:-len(Path(arc).suffix) or None], Path(arc).suffix, 2
            while arc in used:
                arc = "%s (%d)%s" % (stem, i, ext)
                i += 1
            used.add(arc)
            ok = src.exists()
            if ok:
                z.write(str(src), arc)
            qarc = ""
            qp = qr_path(r) if "qr" in r.keys() else None
            if ok and qp and qp.exists():
                qarc = "QR사진/" + arc[:-len(Path(arc).suffix) or None] + qp.suffix
                z.write(str(qp), qarc)
            listing.append([r["id"], r["lang"], r["set_code"], r["card_no"], r["eff_grade"], r["name_ko"] or r["title"],
                            r["memo"], arc if ok else "", "" if ok else "원본 파일 없음", r["info_no"] or "",
                            r["name_jp"], r["tan"], r["ctype"], r["brand"], r["source"], r["part"], r["codi"], r["qty"],
                            r["info_memo"], 1 if r["liked"] else 0, qarc])
        buf = io.StringIO()
        w = csv.writer(buf)
        w.writerow(["ID", "언어", "세트", "카드번호", "등급", "카드명", "메모", "ZIP 안 경로", "비고", "정보 번호",
                    "일본어 이름", "탄", "타입", "브랜드", "배출처", "부위", "코디", "수량", "정보 메모", "좋아요", "QR 경로"])
        w.writerows(listing)
        z.writestr("카드목록.csv", ("\ufeff" + buf.getvalue()).encode("utf-8"))


