MANIFEST = json.dumps({
    "name": "카드 이미지 DB", "short_name": "카드DB", "lang": "ko", "start_url": "/", "scope": "/",
    "display": "standalone", "orientation": "any", "background_color": "#fff2f6", "theme_color": "#f5bccf",
    "icons": [{"src": "/icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any"},
              {"src": "/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any"},
              {"src": "/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "maskable"}],
}, ensure_ascii=False)

SERVICE_WORKER = """
const SHELL='carddb-v1';
self.addEventListener('install',e=>{self.skipWaiting();});
self.addEventListener('activate',e=>{e.waitUntil(self.clients.claim());});
self.addEventListener('fetch',e=>{
  const u=new URL(e.request.url);
  if(e.request.method!=='GET'||u.pathname!=='/')return;   // 화면만 캐시, 데이터는 항상 서버에서
  e.respondWith(fetch(e.request).then(r=>{const c=r.clone();caches.open(SHELL).then(x=>x.put(e.request,c));return r;})
    .catch(()=>caches.match(e.request)));
});
"""

_ICON_CACHE = {}


def make_icon(size):
    """추가 라이브러리 없이 앱 아이콘 PNG 생성 (남색 바탕에 카드 모양)"""
    if size in _ICON_CACHE:
        return _ICON_CACHE[size]
    import struct
    import zlib
    bg, white, band, edge = (0xe0, 0x7f, 0xa3), (0xff, 0xff, 0xff), (0xf0, 0xa8, 0xc1), (0xfd, 0xe3, 0xec)
    rows = []
    x0, x1, y0, y1 = size * .27, size * .73, size * .17, size * .83
    for y in range(size):
        row = bytearray(b"\x00")
        for x in range(size):
            if x0 <= x <= x1 and y0 <= y <= y1:
                if x < x0 + size * .03 or x > x1 - size * .03 or y < y0 + size * .03 or y > y1 - size * .03:
                    c = edge
                elif y0 + size * .08 <= y <= y0 + size * .40 and x0 + size * .07 <= x <= x1 - size * .07:
                    c = band
                elif y1 - size * .26 <= y <= y1 - size * .21 and x0 + size * .07 <= x <= x1 - size * .07:
                    c = band
                elif y1 - size * .16 <= y <= y1 - size * .12 and x0 + size * .07 <= x <= x0 + size * .30:
                    c = band
                else:
                    c = white
            else:
                c = bg
            row += bytes(c)
        rows.append(bytes(row))

    def chunk(t, d):
        return struct.pack(">I", len(d)) + t + d + struct.pack(">I", zlib.crc32(t + d) & 0xffffffff)

    png = (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", size, size, 8, 2, 0, 0, 0))
           + chunk(b"IDAT", zlib.compress(b"".join(rows), 9)) + chunk(b"IEND", b""))
    _ICON_CACHE[size] = png
    return png


APP_FILES = {
    "/manifest.webmanifest": ("application/manifest+json; charset=utf-8", lambda: MANIFEST.encode("utf-8")),
    "/sw.js": ("text/javascript; charset=utf-8", lambda: SERVICE_WORKER.encode("utf-8")),
    "/icon-192.png": ("image/png", lambda: make_icon(192)),
    "/icon-512.png": ("image/png", lambda: make_icon(512)),
    "/apple-touch-icon.png": ("image/png", lambda: make_icon(180)),
    "/favicon.ico": ("image/png", lambda: make_icon(48)),
    "/fonts/GowunDodum-Regular.woff2": ("font/woff2", lambda: font_bytes("body")),
    "/fonts/Jua-Regular.woff2": ("font/woff2", lambda: font_bytes("display")),
}


# ---------------------------------------------------------------- HTTP 서버
class Handler(BaseHTTPRequestHandler):
    server_version = "CardDB/1.0"

    def log_message(self, *a):
        pass

    def send_json(self, obj, code=200):
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def send_zip(self, rows, name):
        self.send_response(200)
        self.send_header("Content-Type", "application/zip")
        self.send_header("Content-Disposition", "attachment; filename*=UTF-8''" + quote(name))
        self.send_header("Connection", "close")
        self.end_headers()
        self.close_connection = True
        try:
            stream_zip(self.wfile, rows)
        except (ConnectionError, BrokenPipeError):
            pass  # 사용자가 다운로드를 취소함

    def send_file_download(self, body, name):
        self.send_response(200)
        self.send_header("Content-Type", "text/csv; charset=utf-8")
        self.send_header("Content-Disposition", "attachment; filename*=UTF-8''" + quote(name))
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def read_body(self):
        n = int(self.headers.get("Content-Length") or 0)
        return self.rfile.read(n) if n else b""

    def read_json(self):
        b = self.read_body()
        return json.loads(b.decode("utf-8")) if b else {}

    def authorized(self):
        if not PASSWORD:
            return True
        h = self.headers.get("Authorization", "")
        if h.startswith("Basic "):
            try:
                pw = base64.b64decode(h[6:]).decode("utf-8").split(":", 1)[1]
                if hmac.compare_digest(pw.encode("utf-8"), PASSWORD.encode("utf-8")):
                    return True
            except Exception:  # noqa
                pass
        self.send_response(401)
        self.send_header("WWW-Authenticate", 'Basic realm="CardDB", charset="UTF-8"')
        self.send_header("Content-Length", "0")
        self.end_headers()
        return False

    def handle_safe(self, fn):
        if not self.authorized():
            return
        try:
            fn()
        except Exception as e:  # noqa
            traceback.print_exc()
            try:
                self.send_json({"error": str(e)}, 500)
            except Exception:  # noqa
                pass

    # ---------- GET
    def do_GET(self):
        global LAST_SEEN
        LAST_SEEN = time.time()
        if urlparse(self.path).path == "/api/ping":   # 실행 확인·화면이 열려 있음 알림 (로그인 불필요)
            self.send_json({"app": "carddb", "readonly": READONLY})
            return
        app = APP_FILES.get(urlparse(self.path).path)
        if app:  # 앱 설치용 파일은 로그인 없이 제공 (홈 화면 아이콘이 보이도록)
            body = app[1]()
            self.send_response(200)
            self.send_header("Content-Type", app[0])
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-cache" if app[0].startswith("text/javascript") else "max-age=86400")
            self.end_headers()
            self.wfile.write(body)
            return
        self.handle_safe(self._get)

    def _get(self):
        u = urlparse(self.path)
        qs = parse_qs(u.query, keep_blank_values=True)
        path = u.path

        if path == "/":
            body = PAGE.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return

        if path.startswith("/api/file/"):  # 한 장 다운로드 (원래 파일명)
            con = db()
            row = con.execute("SELECT * FROM cards WHERE id=?", (int(path.rsplit("/", 1)[1]),)).fetchone()
            con.close()
            if not row or not abs_path(row).exists():
                self.send_json({"error": "파일이 없습니다."}, 404)
                return
            data = abs_path(row).read_bytes()
            self.send_response(200)
            self.send_header("Content-Type", mimetypes.guess_type(row["file_name"])[0] or "application/octet-stream")
            self.send_header("Content-Disposition", "attachment; filename*=UTF-8''" + quote(row["file_name"]))
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
            return

        if path == "/api/download.zip":  # 전체 또는 검색 결과 ZIP
            con = db()
            if qs.get("all", [""])[0] == "1":
                rows = con.execute(SELECT_X + " ORDER BY c.sort_key, c.lang, c.id").fetchall()
                name = "카드이미지_전체_%s.zip" % time.strftime("%Y%m%d")
            else:
                where, p = build_where(qs)
                rows = con.execute(SELECT_X + where + order_by(con, qs), p).fetchall()
                name = "카드이미지_검색결과_%d장_%s.zip" % (len(rows), time.strftime("%Y%m%d"))
            con.close()
            self.send_zip(rows, name)
            return

        if path.startswith("/qr/"):             # 카드의 QR 사진
            con = db()
            row = con.execute("SELECT qr FROM cards WHERE id=?", (int(path[4:] or 0),)).fetchone()
            con.close()
            p = qr_path(row)
            if not p or not p.exists():
                self.send_response(404)
                self.end_headers()
                return
            data = p.read_bytes()
            self.send_response(200)
            self.send_header("Content-Type", mimetypes.guess_type(p.name)[0] or "image/jpeg")
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "no-cache")
            self.end_headers()
            self.wfile.write(data)
            return

        if path.startswith("/img/"):
            con = db()
            row = con.execute("SELECT * FROM cards WHERE id=?", (int(path[5:]),)).fetchone()
            con.close()
            if not row or not abs_path(row).exists():
                self.send_response(404)
                self.end_headers()
                return
            data = abs_path(row).read_bytes()
            self.send_response(200)
            self.send_header("Content-Type", mimetypes.guess_type(row["file_name"])[0] or "application/octet-stream")
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "max-age=86400")
            self.end_headers()
            self.wfile.write(data)
            return

        con = db()
        try:
            if path == "/api/cards":
                where, p = build_where(qs)
                size = max(1, min(10000, int(qs.get("size", ["120"])[0])))
                page = max(0, int(qs.get("page", ["0"])[0]))
                total = con.execute("SELECT COUNT(*)" + FROMX + where, p).fetchone()[0]
                rows = con.execute(SELECT_X + where + order_by(con, qs) + " LIMIT ? OFFSET ?",
                                   p + [size, page * size]).fetchall()
                self.send_json({"total": total, "items": [row_dict(r) for r in rows]})

            elif path.startswith("/api/cards/"):
                cid = int(path.rsplit("/", 1)[1])
                r = con.execute(SELECT_X + " WHERE c.id=?", (cid,)).fetchone()
                if not r:
                    self.send_json({"error": "없는 카드입니다."}, 404)
                    return
                same = []
                if r["info_key"]:
                    same = con.execute("SELECT id, lang, grade, title, file_name FROM cards WHERE info_key=? AND id<>? "
                                       "ORDER BY id LIMIT 20", (r["info_key"], cid)).fetchall()
                elif r["card_no"]:
                    same = con.execute("SELECT id, lang, grade, title, file_name FROM cards WHERE card_no=? AND id<>? "
                                       "ORDER BY lang LIMIT 20", (r["card_no"], cid)).fetchall()
                d = row_dict(r)
                d["position"], d["count"] = user_position(con, cid, qs)
                d["same_codi"] = []
                if r["codi"]:
                    d["same_codi"] = [dict(x) for x in con.execute(
                        "SELECT c.id, c.file_name, COALESCE(i.name_ko,'') AS name_ko, COALESCE(i.no,c.card_no) AS no, "
                        "COALESCE(i.tan,'') AS tan, COALESCE(i.part,'') AS part, c.liked" + FROMX +
                        " WHERE i.codi=? ORDER BY CASE WHEN COALESCE(i.tan,'')=? THEN 0 ELSE 1 END, tan_rank(i.tan), "
                        "part_rank(i.part), num_key(i.no), c.lang, c.id", (r["codi"], r["tan"]))]
                d["similar"] = []
                if r["sim_group"] is not None:
                    d["similar"] = [dict(x) for x in con.execute(
                        "SELECT c.id, c.file_name, COALESCE(i.name_ko,'') AS name_ko, COALESCE(i.no,c.card_no) AS no, c.hash_item"
                        + FROMX + " WHERE c.sim_group=? AND c.id<>? ORDER BY c.sort_key LIMIT 24", (r["sim_group"], cid))]
                    for x in d["similar"]:      # 지문 거리 → 닮은 정도(%)
                        try:
                            dist = bin(int(x["hash_item"], 16) ^ int(r["hash_item"], 16)).count("1")
                            x["score"] = max(0, round(100 - dist * 100 / 256))
                        except (TypeError, ValueError):
                            x["score"] = None
                        x.pop("hash_item", None)
                d["extra"] = {}
                if r["info_key"]:
                    ex = con.execute("SELECT extra FROM card_info WHERE no_key=?", (r["info_key"],)).fetchone()
                    try:
                        d["extra"] = json.loads(ex[0]) if ex and ex[0] else {}
                    except ValueError:
                        pass
                d["abs_path"] = str(abs_path(r))
                d["exists"] = abs_path(r).exists()
                d["same"] = [dict(x) for x in same]
                self.send_json(d)

            elif path == "/api/facets":
                grades = get_grades(con)
                out = {"total": con.execute("SELECT COUNT(*) FROM cards").fetchone()[0], "grades_order": grades}
                for key, col in FILTERS:
                    out[key] = [[r[0] or "(없음)", r[1]] for r in
                                con.execute("SELECT %s AS v, COUNT(*)%s GROUP BY v" % (col, FROMX))]
                out["nonum"] = con.execute("SELECT COUNT(*) FROM cards WHERE card_no=''").fetchone()[0]
                out["nograde"] = con.execute("SELECT COUNT(*)" + FROMX + " WHERE " + EFF_GRADE + "=''").fetchone()[0]
                out["noinfo"] = con.execute("SELECT COUNT(*)" + FROMX + " WHERE i.no_key IS NULL").fetchone()[0]
                out["liked"] = con.execute("SELECT COUNT(*) FROM cards WHERE liked=1").fetchone()[0]
                out["unanalyzed"] = con.execute("SELECT COUNT(*) FROM cards WHERE COALESCE(feat_ver,0) < ?",
                                                (FEAT_VER,)).fetchone()[0]
                out["similar"] = con.execute("SELECT COUNT(*) FROM cards WHERE sim_group IS NOT NULL").fetchone()[0]
                out["sim_groups"] = con.execute("SELECT COUNT(DISTINCT sim_group) FROM cards").fetchone()[0]
                out["colors"] = [[n, con.execute("SELECT COUNT(*) FROM cards WHERE (',' || COALESCE(colors,'') || ',') LIKE ?",
                                                 ("%," + n + ",%",)).fetchone()[0]] for n in COLOR_NAMES]
                row = con.execute("SELECT value FROM settings WHERE key='sim_threshold'").fetchone()
                out["sim_threshold"] = int(row[0]) if row else 40
                out["feat_ver"] = FEAT_VER
                out["order_backup"] = bool(con.execute("SELECT 1 FROM settings WHERE key='user_order_backup'").fetchone())
                out["info_total"] = con.execute("SELECT COUNT(*) FROM card_info").fetchone()[0]
                out["no_image"] = con.execute("SELECT COUNT(*) FROM card_info WHERE no_key NOT IN "
                                              "(SELECT info_key FROM cards WHERE info_key IS NOT NULL)").fetchone()[0]
                out["bytes"] = con.execute("SELECT COALESCE(SUM(size),0) FROM cards").fetchone()[0]
                out["readonly"] = READONLY
                self.send_json(out)

            elif path == "/api/ui":            # 마지막 화면 설정 (정렬·보기·페이지당)
                row = con.execute("SELECT value FROM settings WHERE key='ui'").fetchone()
                try:
                    ui = json.loads(row[0]) if row and row[0] else {}
                except ValueError:
                    ui = {}
                self.send_json({"ui": ui, "readonly": READONLY})

            elif path == "/api/settings":
                self.send_json({"grades": ", ".join(get_grades(con)), "db": str(DB_PATH), "store": str(STORE)})

            elif path == "/api/job":
                with JOB_LOCK:
                    j = dict(JOB)
                end = j["finished"] or time.time()
                j["elapsed"] = max(0.0, end - j["started"]) if j["started"] else 0
                self.send_json(j)

            elif path == "/api/job/log":
                with JOB_LOCK:
                    lf = JOB["log_file"]
                if not lf or not Path(lf).exists():
                    self.send_json({"error": "결과 로그가 없습니다."}, 404)
                    return
                self.send_file_download(Path(lf).read_bytes(), Path(lf).name)

            elif path == "/api/csv-template":
                body = "\ufeff파일경로,카드번호,등급,카드명,세트,언어,메모\r\n" \
                       "D:\\카드이미지\\OP01-001.png,OP01-001,SR,몽키 D 루피,OP01,한국어,\r\n" \
                       "일본판\\OP01-001_jp.png,OP01-001,SR,モンキー・D・ルフィ,OP01,일본어,CSV 기준 상대경로도 가능\r\n"
                self.send_file_download(body.encode("utf-8"), "대량등록_양식.csv")

            elif path == "/api/export.csv":
                where, p = build_where(qs)
                rows = con.execute(SELECT_X + where + order_by(con, qs), p).fetchall()
                buf = io.StringIO()
                w = csv.writer(buf)
                w.writerow(["순서", "ID", "번호", "이름", "일본어 이름", "탄", "등급", "타입", "브랜드", "배출처", "부위",
                            "코디", "수량", "정보 메모", "카드 메모", "언어", "파일명", "저장경로", "등록일", "좋아요", "대표 색", "색상", "비슷한 이미지 묶음"])
                for n, r in enumerate(rows, 1):
                    w.writerow([n, r["id"], r["info_no"] or r["card_no"], r["name_ko"] or r["title"], r["name_jp"], r["tan"],
                                r["eff_grade"], r["ctype"], r["brand"], r["source"], r["part"], r["codi"], r["qty"],
                                r["info_memo"], r["memo"], r["lang"], r["file_name"], str(abs_path(r)), r["created_at"],
                                "♥" if r["liked"] else "", r["color_main"] or "", r["colors"] or "",
                                r["sim_group"] if r["sim_group"] is not None else ""])
                self.send_file_download(("\ufeff" + buf.getvalue()).encode("utf-8"), "카드목록.csv")

            elif path == "/api/codis":           # 코디 이름 목록 (자동완성용)
                self.send_json({"items": [[r[0], r[1]] for r in con.execute(
                    "SELECT i.codi, COUNT(c.id) FROM card_info i LEFT JOIN cards c ON c.info_key=i.no_key "
                    "WHERE COALESCE(i.codi,'')<>'' GROUP BY i.codi ORDER BY MIN(tan_rank(i.tan)), i.codi")]})

            elif path == "/api/features/todo":   # 아직 분석하지 않은 카드
                ids = [r[0] for r in con.execute("SELECT id FROM cards WHERE COALESCE(feat_ver,0) < ? ORDER BY id",
                                                 (FEAT_VER,))] if qs.get("all", [""])[0] != "1" else \
                      [r[0] for r in con.execute("SELECT id FROM cards ORDER BY id")]
                self.send_json({"ids": ids})

            elif path == "/api/features/hashes":   # 묶음 계산용 이미지 지문 전체
                self.send_json({"items": [[r[0], r[1], r[2]] for r in con.execute(
                    "SELECT id, orient, hash_item FROM cards WHERE hash_item IS NOT NULL AND hash_item<>''")]})

            elif path == "/api/info/search":     # 카드 정보 검색 (번호·이름·일본어 이름)
                q = nfc(qs.get("q", [""])[0]).strip()
                lim = max(1, min(50, int(qs.get("limit", ["20"])[0])))
                if not q:
                    self.send_json({"items": []})
                    return
                like = "%" + q + "%"
                rows = con.execute(
                    "SELECT i.*, (SELECT COUNT(*) FROM cards c WHERE c.info_key=i.no_key) AS images FROM card_info i "
                    "WHERE i.no_key=? OR i.no_key LIKE ? OR i.no LIKE ? OR i.name_ko LIKE ? OR i.name_jp LIKE ? "
                    "ORDER BY CASE WHEN i.no_key=? THEN 0 WHEN i.no_key LIKE ? THEN 1 ELSE 2 END, i.no LIMIT ?",
                    (info_key(q), "%" + info_key(q) + "%", like, like, like, info_key(q), info_key(q) + "%", lim)).fetchall()
                self.send_json({"items": [dict(r) for r in rows]})

            elif path == "/api/info/get":        # 번호 하나의 카드 정보
                r = con.execute("SELECT i.*, (SELECT COUNT(*) FROM cards c WHERE c.info_key=i.no_key) AS images "
                                "FROM card_info i WHERE no_key=?", (info_key(qs.get("no", [""])[0]),)).fetchone()
                self.send_json({"item": dict(r) if r else None})

            elif path == "/api/info/missing.csv":   # 텍스트에는 있지만 이미지가 없는 카드
                rows = con.execute("SELECT * FROM card_info WHERE no_key NOT IN (SELECT info_key FROM cards "
                                   "WHERE info_key IS NOT NULL) ORDER BY no").fetchall()
                buf = io.StringIO()
                w = csv.writer(buf)
                w.writerow(INFO_LABELS)
                for r in rows:
                    w.writerow([r[f] for f in INFO_FIELDS])
                self.send_file_download(("\ufeff" + buf.getvalue()).encode("utf-8"), "이미지없는카드목록.csv")
            else:
                self.send_json({"error": "not found"}, 404)
        finally:
            con.close()

    # ---------- POST
    def do_POST(self):
        global LAST_SEEN
        LAST_SEEN = time.time()
        self.handle_safe(self._post)

    def _post(self):
        path = urlparse(self.path).path
        if path == "/api/download.zip":  # 선택한 카드 ZIP (폼 전송: ids=1,2,3)
            body = self.read_body().decode("utf-8")
            if "json" in (self.headers.get("Content-Type") or ""):
                ids = json.loads(body or "{}").get("ids", [])
            else:
                ids = (parse_qs(body).get("ids", [""])[0]).split(",")
            order = (parse_qs(body).get("sort", [""])[0]) if "json" not in (self.headers.get("Content-Type") or "") else ""
            ids = [int(x) for x in ids if str(x).strip().isdigit()][:100000]
            con = db()
            rows = []
            for i in range(0, len(ids), 900):
                chunk = ids[i:i + 900]
                rows += con.execute(SELECT_X + " WHERE c.id IN (%s)" % ",".join("?" * len(chunk)), chunk).fetchall()
            con.close()
            rows.sort(key=lambda r: (r["user_order"] or 0, r["id"]) if order == "user" else (r["sort_key"], r["lang"], r["id"]))
            self.send_zip(rows, "카드이미지_선택_%d장_%s.zip" % (len(rows), time.strftime("%Y%m%d")))
            return
        if READONLY:
            self.send_json({"error": "읽기 전용 모드입니다. 등록·수정·삭제할 수 없습니다."}, 403)
            return
        if path == "/api/ui":                    # 마지막 화면 설정 저장
            req = self.read_json()
            ui = {k: str(req[k])[:20] for k in ("sort", "view", "psize") if k in req}
            con = db()
            try:
                old = con.execute("SELECT value FROM settings WHERE key='ui'").fetchone()
                cur = json.loads(old[0]) if old and old[0] else {}
                cur.update(ui)
                con.execute("INSERT OR REPLACE INTO settings(key, value) VALUES('ui', ?)", (json.dumps(cur),))
                con.commit()
            finally:
                con.close()
            self.send_json({"ok": True})
            return
        con = db()
        try:
            m_qr = re.match(r"^/api/cards/(\d+)/qr(/delete)?$", path)
            if m_qr:                            # QR 사진 넣기·바꾸기 / 지우기
                cid = int(m_qr.group(1))
                if not con.execute("SELECT 1 FROM cards WHERE id=?", (cid,)).fetchone():
                    self.send_json({"error": "카드가 없습니다."}, 404)
                    return
                data, ext = None, ".jpg"
                if not m_qr.group(2):
                    data = self.read_body()
                    if not data:
                        self.send_json({"error": "사진이 비어 있습니다."}, 400)
                        return
                    ext = Path(unquote(self.headers.get("X-Filename", "qr.jpg"))).suffix.lower()
                    if ext not in QR_EXT:
                        ext = ".jpg"
                remove_qr(con, cid)
                if data:
                    qr_dir().mkdir(parents=True, exist_ok=True)
                    name = "%d_%d%s" % (cid, int(time.time()), ext)
                    (qr_dir() / name).write_bytes(data)
                    con.execute("UPDATE cards SET qr=? WHERE id=?", (name, cid))
                con.commit()
                self.send_json({"ok": True, "qr": bool(data)})
                return
            if path == "/api/upload":
                fname = unquote(self.headers.get("X-Filename", "image.png"))
                dup = "update" if self.headers.get("X-Dup") == "update" else "skip"
                data = self.read_body()
                hint = unquote(self.headers.get("X-Path", ""))
                st, cid = register(con, fname, data=data, dup=dup, meta_over={"_hint": hint} if hint else None)
                con.commit()
                self.send_json({"status": st, "id": cid})

            elif path == "/api/upload-temp":  # ZIP·CSV 파일을 임시 폴더에 올림
                fname = safe_part(nfc(unquote(self.headers.get("X-Filename", "upload.zip"))), "upload.zip")
                target = temp_dir() / ("%s_%s" % (uuid.uuid4().hex[:8], fname))
                n, left = 0, int(self.headers.get("Content-Length") or 0)
                with open(str(target), "wb") as f:
                    while left > 0:
                        chunk = self.rfile.read(min(left, 1 << 20))
                        if not chunk:
                            break
                        f.write(chunk)
                        left -= len(chunk)
                self.send_json({"path": str(target)})

            elif path in ("/api/import", "/api/preview"):
                req = self.read_json()
                paths = req.get("paths") or ([req["path"]] if req.get("path") else [])
                csv_file = str(req.get("csv") or "").strip()
                if not paths and not csv_file:
                    self.send_json({"error": "등록할 경로나 CSV를 입력하세요."}, 400)
                    return
                if path == "/api/preview":
                    self.send_json(preview(paths, csv_file))
                    return
                ok = start_job(paths, csv_file, bool(req.get("copy", True)),
                               "update" if req.get("dup") == "update" else "skip", req.get("cleanup") or [])
                if not ok:
                    self.send_json({"error": "이미 등록 작업이 진행 중입니다."}, 409)
                    return
                self.send_json({"ok": True})

            elif path == "/api/job/cancel":
                with JOB_LOCK:
                    JOB["cancel"] = True
                self.send_json({"ok": True})

            elif path == "/api/delete":
                ids = self.read_json().get("ids", [])
                self.send_json({"deleted": delete_cards(con, ids)})

            elif path == "/api/settings":
                g = str(self.read_json().get("grades", "")).strip() or DEFAULT_GRADES
                con.execute("INSERT OR REPLACE INTO settings(key, value) VALUES('grades', ?)", (g,))
                con.commit()
                self.send_json({"ok": True})

            elif path == "/api/reparse":
                grades = get_grades(con)
                rows = con.execute("SELECT id, file_name FROM cards").fetchall()
                for r in rows:
                    m = parse_name(r["file_name"], grades)
                    con.execute("UPDATE cards SET lang=?, set_code=?, card_no=?, grade=?, title=?, sort_key=?, "
                                "updated_at=datetime('now','localtime') WHERE id=?",
                                (m["lang"], m["set_code"], m["card_no"], m["grade"], m["title"], m["sort_key"], r["id"]))
                link_all(con)
                con.commit()
                self.send_json({"updated": len(rows)})

            elif path == "/api/info/import":     # 카드 정보 텍스트 가져오기
                raw = self.read_body()
                st = import_info(con, raw, replace_all=self.headers.get("X-Replace") == "1")
                self.send_json(st)

            elif path == "/api/features":        # 브라우저가 분석한 색상·이미지 지문 저장
                req = self.read_json()
                rows = []
                for it in req.get("items", []):
                    try:
                        cols_l = [c for c in it.get("colors", []) if c[0] in COLOR_NAMES]
                        rows.append((cols_l[0][0] if cols_l else "",
                                     ",".join(c[0] for c in cols_l if c[1] >= 15) or (cols_l[0][0] if cols_l else ""),
                                     json.dumps(cols_l, ensure_ascii=False), str(it.get("hash_all", ""))[:128],
                                     str(it.get("hash_item", ""))[:128], "H" if it.get("orient") == "H" else "V",
                                     FEAT_VER, int(it["id"])))
                    except (KeyError, ValueError, TypeError, IndexError):
                        continue
                con.executemany("UPDATE cards SET color_main=?, colors=?, palette=?, hash_all=?, hash_item=?, orient=?, "
                                "feat_ver=? WHERE id=?", rows)
                con.commit()
                self.send_json({"saved": len(rows)})

            elif path == "/api/simgroups":       # 비슷한 이미지 묶음 저장 (브라우저에서 계산)
                req = self.read_json()
                groups = req.get("groups", {})
                con.execute("UPDATE cards SET sim_group=NULL")
                con.executemany("UPDATE cards SET sim_group=? WHERE id=?", [(int(g), int(i)) for i, g in groups.items()])
                if req.get("threshold"):
                    con.execute("INSERT OR REPLACE INTO settings(key, value) VALUES('sim_threshold', ?)",
                                (str(int(req["threshold"])),))
                con.commit()
                self.send_json({"cards": len(groups), "groups": len(set(groups.values()))})

            elif path == "/api/relink":          # 카드 ↔ 카드 정보 전체 다시 연결
                linked, total_cards = link_all(con)
                con.commit()
                self.send_json({"linked": linked, "cards": total_cards})

            elif path == "/api/like":            # 좋아요(원해요) 켜기·끄기
                req = self.read_json()
                ids = [int(x) for x in req.get("ids", [])]
                val = 1 if req.get("liked") else 0
                con.executemany("UPDATE cards SET liked=? WHERE id=?", [(val, i) for i in ids])
                con.commit()
                self.send_json({"ok": True, "count": len(ids), "liked": val})

            elif path == "/api/bulk/codi":       # 선택한 카드들의 코디 이름 한 번에 지정 (빈 값 = 지우기)
                req = self.read_json()
                codi = nfc(str(req.get("codi", ""))).strip()
                n = 0
                for cid in [int(x) for x in req.get("ids", [])]:
                    row = con.execute("SELECT info_key, file_name FROM cards WHERE id=?", (cid,)).fetchone()
                    if not row:
                        continue
                    k = row["info_key"]
                    if not k:      # 카드 정보가 없던 카드 → 파일명을 번호로 새로 만듦
                        no = Path(row["file_name"]).stem
                        k = info_key(no)
                        if not con.execute("SELECT 1 FROM card_info WHERE no_key=?", (k,)).fetchone():
                            con.execute("INSERT INTO card_info(no_key, no) VALUES(?,?)", (k, no))
                        con.execute("UPDATE cards SET info_key=? WHERE id=?", (k, cid))
                    con.execute("UPDATE card_info SET codi=?, updated_at=datetime('now','localtime') WHERE no_key=?", (codi, k))
                    n += 1
                con.commit()
                self.send_json({"count": n})

            elif path == "/api/userorder/arrange":   # 사용자 정렬: 색상별·이미지별·번호순으로 한 번에
                req = self.read_json()
                mode = req.get("mode")
                if mode not in ("color", "similar", "num", "codi"):
                    self.send_json({"error": "알 수 없는 방식"}, 400)
                    return
                n = arrange_user_order(con, parse_qs(req.get("qs", ""), keep_blank_values=True), mode)
                self.send_json({"count": n})

            elif path == "/api/userorder/undo":      # 마지막 한 번에 정렬 되돌리기
                row = con.execute("SELECT value FROM settings WHERE key='user_order_backup'").fetchone()
                if not row:
                    self.send_json({"error": "되돌릴 내용이 없습니다."}, 400)
                    return
                backup = json.loads(row[0])
                con.executemany("UPDATE cards SET user_order=? WHERE id=?", [(v, int(k)) for k, v in backup.items()])
                con.execute("DELETE FROM settings WHERE key='user_order_backup'")
                fill_user_order(con)
                con.commit()
                self.send_json({"count": len(backup)})

            elif path == "/api/reorder":         # 사용자 정렬: 위치 이동
                req = self.read_json()
                qs2 = parse_qs(req.get("qs", ""), keep_blank_values=True)
                adopted = adopt_sort_order(con, qs2)   # 사용자 정렬이 아니면 지금 보이는 순서를 먼저 가져옴
                ok = reorder(con, req.get("ids", []), qs2, req.get("target"), req.get("side", "before"),
                             req.get("position"))
                self.send_json({"ok": ok, "adopted": adopted})

            elif path.startswith("/api/cards/"):  # 수정
                cid = int(path.rsplit("/", 1)[1])
                req = self.read_json()
                fields = {k: nfc(str(req[k])).strip() for k in ("lang", "set_code", "card_no", "grade", "title", "memo")
                          if k in req}
                if "grade" in fields:
                    fields["grade"] = fields["grade"].upper()
                if "card_no" in fields:
                    fields["card_no"] = fields["card_no"].upper()
                    fields["sort_key"] = make_sort_key(fields["card_no"])
                if fields:
                    sets = ", ".join("%s=?" % k for k in fields)
                    con.execute("UPDATE cards SET %s, updated_at=datetime('now','localtime') WHERE id=?" % sets,
                                list(fields.values()) + [cid])
                # 연결할 카드 정보 번호를 직접 바꾼 경우
                if "info_no" in req:
                    no = nfc(str(req["info_no"])).strip()
                    if no:
                        k = info_key(no)
                        if not con.execute("SELECT 1 FROM card_info WHERE no_key=?", (k,)).fetchone():
                            con.execute("INSERT INTO card_info(no_key, no) VALUES(?,?)", (k, no))
                        con.execute("UPDATE cards SET info_key=?, info_manual=1 WHERE id=?", (k, cid))
                    else:
                        con.execute("UPDATE cards SET info_manual=0 WHERE id=?", (cid,))
                        link_one(con, cid)
                # 카드 정보(이름·일본어 이름·탄 …) 수정
                info = {f: nfc(str(req["i_" + f])).strip() for f in INFO_FIELDS if f != "no" and "i_" + f in req}
                if info:
                    row = con.execute("SELECT info_key, file_name FROM cards WHERE id=?", (cid,)).fetchone()
                    k = row["info_key"]
                    if not k and any(info.values()):     # 정보가 없던 카드 → 파일명을 번호로 새로 만듦
                        no = Path(row["file_name"]).stem
                        k = info_key(no)
                        if not con.execute("SELECT 1 FROM card_info WHERE no_key=?", (k,)).fetchone():
                            con.execute("INSERT INTO card_info(no_key, no) VALUES(?,?)", (k, no))
                        con.execute("UPDATE cards SET info_key=? WHERE id=?", (k, cid))
                    if k:
                        con.execute("UPDATE card_info SET %s, updated_at=datetime('now','localtime') WHERE no_key=?"
                                    % ", ".join("%s=?" % f for f in info), list(info.values()) + [k])
                con.commit()
                self.send_json({"ok": True})
            else:
                self.send_json({"error": "not found"}, 404)
        finally:
            con.close()


